// GH-1075 A2 (A2-28): the win floor the server will hold a victory to. One non-negative integer per world
// mission, a QUARTER of the fastest scripted 30-seed win (Lead decision 9), generated by
// `pnpm playtest -- --min-win` and committed as data. The tutorial is not a world mission and has no floor.
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { worldMissionIds } from '../../packages/economy/src';
import { minWinSeconds, world } from '@lions/data';
import { parseWorld } from '../../packages/app/src/campaign';

const ids = worldMissionIds(parseWorld(world));

describe('min_win_seconds.json (A2-28)', () => {
  it('names every world mission and no other', () => {
    expect(ids.length).toBeGreaterThan(0);
    expect(Object.keys(minWinSeconds).sort()).toEqual([...ids].sort());
  });
  it('holds an integer of at least 0 for each', () => {
    for (const [id, v] of Object.entries(minWinSeconds)) {
      expect(Number.isInteger(v), `${id}: ${v}`).toBe(true);
      expect(v, id).toBeGreaterThanOrEqual(0);
    }
  });
  it('does not name the tutorial', () => {
    expect(Object.keys(minWinSeconds).filter((k) => /tutorial/.test(k))).toEqual([]);
  });
  it('is the file the export reads', () => {
    const raw = JSON.parse(readFileSync('data/accounts/min_win_seconds.json', 'utf8')) as { min_win_seconds: Record<string, number> };
    expect(raw.min_win_seconds).toEqual(minWinSeconds);
  });
});
